-- =============================================================================
-- SwapUp — Complete PostgreSQL Schema (20 Tables incl. Razorpay) + Catalogue +
--          Samsung & Apple Rate Cards (290 rows) + Device Repair Costs (1,520 rows/org)
-- Run with: psql "$DATABASE_URL" -f deploy/postgres-full-seed.sql
--       or: psql -h 127.0.0.1 -U guru_user -d scrapingdb -f deploy/postgres-full-seed.sql
-- =============================================================================

BEGIN;
CREATE SCHEMA IF NOT EXISTS swapup;
SET search_path TO swapup, public;

CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS counters (
  name TEXT PRIMARY KEY,
  value INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS orgs (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  kind TEXT NOT NULL,
  client_type TEXT,
  target_brand TEXT,
  partner_id TEXT,
  settings TEXT NOT NULL DEFAULT '{}',
  demo INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS stores (
  id TEXT PRIMARY KEY,
  org_id TEXT NOT NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL,
  city TEXT,
  code TEXT NOT NULL,
  credit_limit INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  review_note TEXT,
  settings TEXT NOT NULL DEFAULT '{}',
  registered_by TEXT,
  counter_code TEXT,
  UNIQUE(org_id, code)
);

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  org_id TEXT NOT NULL,
  store_id TEXT,
  username TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  role TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  pin_hash TEXT,
  pin_set_at TEXT
);

CREATE TABLE IF NOT EXISTS trade_models (
  id TEXT PRIMARY KEY,
  brand TEXT NOT NULL,
  model TEXT NOT NULL,
  series TEXT,
  release_year INTEGER,
  support_end_year INTEGER,
  variants TEXT NOT NULL DEFAULT '[]',
  service_tier TEXT NOT NULL DEFAULT 'other',
  care_plus_fee INTEGER,
  model_codes TEXT NOT NULL DEFAULT '[]',
  source TEXT
);

CREATE TABLE IF NOT EXISTS new_devices (
  id TEXT PRIMARY KEY,
  org_id TEXT NOT NULL,
  brand TEXT NOT NULL,
  model TEXT NOT NULL,
  series TEXT NOT NULL,
  variant TEXT NOT NULL,
  price INTEGER NOT NULL,
  support_end_year INTEGER,
  active INTEGER NOT NULL DEFAULT 1,
  sort INTEGER NOT NULL DEFAULT 100,
  source TEXT
);

CREATE TABLE IF NOT EXISTS repair_book (
  org_id TEXT NOT NULL,
  model_id TEXT NOT NULL,
  part TEXT NOT NULL,
  price INTEGER NOT NULL,
  source TEXT,
  PRIMARY KEY (org_id, model_id, part)
);

CREATE TABLE IF NOT EXISTS campaigns (
  id TEXT PRIMARY KEY,
  org_id TEXT NOT NULL,
  data TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS rate_cards (
  id TEXT PRIMARY KEY,
  partner_id TEXT NOT NULL,
  data TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 0,
  created_by TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS cases (
  id TEXT PRIMARY KEY,
  ref TEXT NOT NULL UNIQUE,
  org_id TEXT NOT NULL,
  store_id TEXT NOT NULL,
  advisor_id TEXT NOT NULL,
  status TEXT NOT NULL,
  customer TEXT,
  model_id TEXT,
  variant TEXT,
  imei TEXT,
  imei_check TEXT,
  imei2 TEXT,
  imei2_check TEXT,
  closed_reason TEXT,
  faults TEXT NOT NULL DEFAULT '[]',
  coverage TEXT NOT NULL DEFAULT 'none',
  condition TEXT,
  manual_repair TEXT,
  partner_manual TEXT,
  repair TEXT,
  quote TEXT,
  repaired_quote TEXT,
  upgrade TEXT,
  bonus TEXT,
  decision TEXT,
  checks TEXT,
  trade_value INTEGER,
  bonus_value INTEGER,
  payable INTEGER,
  premium_value INTEGER,
  premium_bp INTEGER,
  premium_funded_by TEXT,
  pickup_id TEXT,
  clearance TEXT,
  settled_at TEXT,
  demo INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  locked_at TEXT,
  closed_at TEXT,
  fault_sources TEXT NOT NULL DEFAULT '{}',
  camera_check TEXT,
  data_clear TEXT,
  refurb_cost TEXT,
  variant_source TEXT,
  storage_quotes TEXT,
  measured_storage TEXT,
  certification TEXT,
  report_token TEXT,
  imei_lookup TEXT,
  kym_early TEXT,
  model_source TEXT
);

CREATE TABLE IF NOT EXISTS credit_ledger (
  id SERIAL PRIMARY KEY,
  store_id TEXT NOT NULL,
  case_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  amount INTEGER NOT NULL,
  note TEXT,
  by_user TEXT,
  at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS pickups (
  id TEXT PRIMARY KEY,
  ref TEXT NOT NULL UNIQUE,
  org_id TEXT NOT NULL,
  store_id TEXT NOT NULL,
  partner_id TEXT NOT NULL,
  status TEXT NOT NULL,
  requested_by TEXT,
  requested_at TEXT NOT NULL,
  scheduled_for TEXT,
  collector_name TEXT,
  handover_by TEXT,
  collected_at TEXT,
  reconciled_at TEXT,
  settled_at TEXT,
  settlement_ref TEXT,
  settlement_amount INTEGER,
  notes TEXT,
  demo INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS audit (
  id SERIAL PRIMARY KEY,
  at TEXT NOT NULL,
  user_id TEXT,
  org_id TEXT,
  store_id TEXT,
  action TEXT NOT NULL,
  entity TEXT,
  entity_id TEXT,
  detail TEXT
);

CREATE TABLE IF NOT EXISTS test_sessions (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL,
  case_id TEXT NOT NULL,
  store_id TEXT NOT NULL,
  org_id TEXT NOT NULL,
  created_by TEXT NOT NULL,
  status TEXT NOT NULL,
  plan TEXT NOT NULL DEFAULT '[]',
  install_id TEXT,
  ticket_hash TEXT,
  device TEXT,
  declared TEXT,
  results TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  opened_at TEXT,
  joined_at TEXT,
  completed_at TEXT,
  applied_at TEXT,
  updated_at TEXT NOT NULL,
  gradeiq_id TEXT,
  gradeiq_state TEXT NOT NULL DEFAULT 'disabled',
  gradeiq_error TEXT,
  gradeiq_snapshot TEXT,
  gradeiq_synced_at TEXT,
  gradeiq_forwarded_at TEXT,
  gradeiq_attempts INTEGER NOT NULL DEFAULT 0,
  gradeiq_orphans TEXT NOT NULL DEFAULT '[]',
  gradeiq_screen TEXT,
  gradeiq_screen_at TEXT,
  gradeiq_cosmetic_done_at TEXT,
  gradeiq_device_hash TEXT,
  gradeiq_forward_hash TEXT,
  gradeiq_sync_error TEXT,
  gradeiq_override TEXT,
  gradeiq_devicefax TEXT,
  phone_phase TEXT,
  phone_phase_at TEXT,
  started_via TEXT,
  scan_release TEXT
);

CREATE TABLE IF NOT EXISTS handoff_nonces (
  nonce_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  next TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  used_at TEXT
);

CREATE TABLE IF NOT EXISTS store_invites (
  code_hash TEXT PRIMARY KEY,
  code_hint TEXT NOT NULL,
  store_id TEXT NOT NULL,
  role TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  max_uses INTEGER NOT NULL DEFAULT 5,
  uses INTEGER NOT NULL DEFAULT 0,
  revoked_at TEXT
);

CREATE TABLE IF NOT EXISTS store_devices (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL,
  org_id TEXT NOT NULL,
  name TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  last_seen_at TEXT,
  revoked_at TEXT,
  revoked_by TEXT
);

CREATE TABLE IF NOT EXISTS pin_attempts (
  device_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  failures INTEGER NOT NULL DEFAULT 0,
  locked_until TEXT,
  last_failure_at TEXT,
  PRIMARY KEY (device_id, user_id)
);

CREATE TABLE IF NOT EXISTS market_listings (
  source TEXT NOT NULL,
  model_id TEXT NOT NULL,
  variant TEXT NOT NULL,
  grade TEXT NOT NULL,
  price INTEGER NOT NULL,
  week TEXT NOT NULL,
  listed_as TEXT,
  fetched_at TEXT,
  observed_at TEXT,
  points INTEGER
);

CREATE TABLE IF NOT EXISTS grading_reports (
  id TEXT PRIMARY KEY,
  case_id TEXT NOT NULL,
  version INTEGER NOT NULL,
  reason TEXT NOT NULL,
  ruleset TEXT NOT NULL,
  status TEXT NOT NULL,
  label TEXT NOT NULL,
  final INTEGER NOT NULL DEFAULT 0,
  body TEXT NOT NULL,
  sha256 TEXT NOT NULL,
  photo_sources TEXT NOT NULL DEFAULT '[]',
  issued_at TEXT NOT NULL,
  issued_by TEXT,
  UNIQUE(case_id, version)
);

CREATE TABLE IF NOT EXISTS phonecheck_records (
  id TEXT PRIMARY KEY,
  record_key TEXT NOT NULL UNIQUE,
  source TEXT NOT NULL,
  imei TEXT,
  imei2 TEXT,
  store_id TEXT,
  case_id TEXT,
  tested_at TEXT,
  record TEXT NOT NULL,
  raw TEXT NOT NULL,
  received_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  attached_at TEXT,
  attached_by TEXT,
  attach_override TEXT
);

CREATE TABLE IF NOT EXISTS razorpay_payments (
  id TEXT PRIMARY KEY,
  case_id TEXT NOT NULL,
  case_ref TEXT NOT NULL,
  org_id TEXT NOT NULL,
  store_id TEXT NOT NULL,
  journey TEXT NOT NULL,
  payment_plan TEXT NOT NULL,
  installment_stage TEXT NOT NULL,
  total_case_payable INTEGER NOT NULL,
  amount INTEGER NOT NULL,
  remaining_due INTEGER NOT NULL DEFAULT 0,
  emi_months INTEGER,
  emi_monthly_amount INTEGER,
  currency TEXT NOT NULL DEFAULT 'INR',
  razorpay_order_id TEXT NOT NULL UNIQUE,
  razorpay_payment_id TEXT,
  razorpay_signature TEXT,
  payment_method TEXT,
  status TEXT NOT NULL DEFAULT 'created',
  customer_name TEXT,
  customer_phone TEXT,
  notes TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  paid_at TEXT
);

CREATE INDEX IF NOT EXISTS idx_razorpay_payments_case_id ON razorpay_payments(case_id);

-- 1. Organisations

-- 2. Stores (unique store codes across all programmes)

-- 3. Users (default password: swapup2026)

-- 4. Trade Models (152 models including all Samsung & Apple phones)

-- 5. Complete Device-Specific Repair Book (1520 rows per programme across all 10 parts) & New Upgrade Devices

-- 6. Samsung & Apple Rate Cards (290 model+variant rows each, active = 1)
UPDATE rate_cards SET active = 0 WHERE partner_id IN ('ptn_demo', 'ptn_BfpxCIbbL6RTGPMk');

-- 7. Migration & Seed Meta Flags

COMMIT;
